  "knowledge": "Peer Mimicry Suspicion",
  "description": "Flags traders whose behavior closely matches peers but deviates little from known patterns, potentially mimicking a risky group.",
  "definition": "A trader with a low 'Pattern Anomaly Score' (e.g., < 0.1) BUT a high peer correlation score (e.g., > 0.7)."
}

{
  "id": 62,
  "knowledge": "Networked Mimicry Risk",
  "description": "Flags traders suspected of peer mimicry who are also part of an identified potential collusion network.",
  "definition": "A trader flagged for 'Peer Mimicry Suspicion' AND associated with a 'Collusion Network Indicator'."
}

{
  "id": 13,
  "knowledge": "Collusion Network Indicator",
  "description": "Suggests potential collusion based on investigation details.",
  "definition": "A case indicates potential collusion if the trader circle size > 5 AND the group behavior score > 0.6 AND the communication path is 'Regular'."
}

{
  "id": 50,
  "knowledge": "Investigation Compliance Risk Index (ICRI)",
  "description": "Combines the weighted investigation score with the inverse compliance health score, highlighting cases that are both problematic and under intense investigation.",
  "definition": "ICRI = 'Weighted Investigation Score' \\times (1 - 'Compliance Health Score')"
}

{
  "id": 33,
  "knowledge": "Weighted Investigation Score (WIS)",
  "description": "Combines raw investigation scores with the current alert severity level.",
  "definition": "WIS = 'Investigation Intensity Index' \\times A numeric multiplier based on Alert Level Severity ('Low'=1, 'High'=3, etc.)"
}

{
  "id": 32,
  "knowledge": "Compliance Health Score (CHS)",
  "description": "Inverse score reflecting compliance history severity, penalizing high recidivism and poor ratings.",
  "definition": "CHS = \\frac{1}{1 + \\text{'Compliance Recidivism Score'} \\times \\text{A numeric value mapped from the 'Compliance Rating Grade'}}"
}

{
  "id": 3,
  "knowledge": "Suspicious Activity Index (SAI)",
  "description": "A composite index attempting to quantify overall suspicious trading behavior based on risk indicators.",
  "definition": "SAI is a weighted sum of normalized risk indicators, including probabilities for spoofing, front-running, wash trading, and confirmed layering."
}

{
  "id": 31,
  "knowledge": "Combined Manipulation Indicator (CMI)",
  "description": "A combined score reflecting both general suspicious activity and specific pattern anomalies.",
  "definition": "CMI = ('Suspicious Activity Index' + 'Pattern Anomaly Score') / 2"
}

{
  "id": 4,
  "knowledge": "Pattern Anomaly Score (PAS)",
  "description": "Measures the deviation of a trader's pattern similarity from their peer correlation, potentially indicating unique illicit behavior.",
  "definition": "PAS = |\\text{Pattern Similarity Score} - \\text{Peer Correlation Score}|"
}

